public protocol LotDocumentProtocol: AnyObject, Sendable {
    
    /**
     * Legt eine Datei im Projekt ab, etwa eine Unterlage. Gleicher Name ersetzt.
     */
    func addAttachment(name: String, data: Data) 
    
    /**
     * Inhalt eines 2D-Texts; `None`, wenn das Element kein Text ist.
     */
    func annotationText(element: UInt64)  -> String?
    
    /**
     * Schrifthöhe eines 2D-Texts in mm; `None`, wenn das Element kein Text ist.
     */
    func annotationTextHeight(element: UInt64)  -> Double?
    
    /**
     * Inhalt einer Datei im Projekt.
     */
    func attachment(name: String)  -> Data?
    
    func canRedo()  -> Bool
    
    func canUndo()  -> Bool
    
    /**
     * Die Türen unter den Elementen `ids`.
     */
    func doors(ids: [UInt64])  -> [DoorInfo]
    
    /**
     * Bezeichnung eines Elements für die Anzeige, etwa „Wand · Außenwand WDVS 36“.
     */
    func elementLabel(element: UInt64)  -> String
    
    /**
     * Bauzustand eines Elements: 0 Bestand, 1 Abbruch, 2 Neubau; `None`, wenn es keinen hat.
     */
    func elementPhase(element: UInt64)  -> UInt32?
    
    func name()  -> String
    
    /**
     * Alle änderbaren Parameter der Elemente `ids`, oder aller Elemente, wenn `ids` leer ist.
     */
    func parameters(ids: [UInt64])  -> [ParamValue]
    
    func redo() throws  -> Bool
    
    func save(path: String) throws 
    
    /**
     * Ändert Inhalt und Schrifthöhe (mm auf dem Papier) eines 2D-Texts.
     */
    func setAnnotationText(element: UInt64, text: String, height: Double) throws 
    
    func setParam(element: UInt64, kind: ParamKind, value: Double) throws 
    
    /**
     * Ändert Nummer, Name, Nutzung und Wohnflächen-Merkmal eines Raums, als eine Operation.
     */
    func setSpace(element: UInt64, number: String, name: String, usage: UInt32, livingSpace: Bool) throws 
    
    /**
     * Raumdaten der gewählten Elemente, die Räume sind.
     */
    func spaces(ids: [UInt64])  -> [SpaceInfo]
    
    /**
     * Flächen je Geschoss (NRF, BGF, Wohnfläche).
     */
    func storeyAreas()  -> [StoreyAreaInfo]
    
    func undo() throws  -> Bool
    
}
