#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLotDocument: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = LotDocument

    public static func lift(_ handle: UInt64) throws -> LotDocument {
        return LotDocument(unsafeFromHandle: handle)
    }

    public static func lower(_ value: LotDocument) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LotDocument {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: LotDocument, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLotDocument_lift(_ handle: UInt64) throws -> LotDocument {
    return try FfiConverterTypeLotDocument.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLotDocument_lower(_ value: LotDocument) -> UInt64 {
    return FfiConverterTypeLotDocument.lower(value)
}






public protocol ViewportProtocol: AnyObject, Sendable {
    
    /**
     * Legt eine Unterlage aus einer DXF- oder DWG-Datei im Projekt an (vorher
     * mit `add_attachment` abgelegt). Maßstab nach den Einheiten der Datei;
     * liegen ihre Koordinaten nahe am Ursprung, bleiben sie, sonst kommt die
     * Zeichnung in die Mitte der Ansicht.
     */
    func addCadUnderlay(source: String) throws  -> UInt64
    
    /**
     * Legt ein Referenzmodell aus einer IFC-Datei im Projekt an (vorher mit
     * `add_attachment` abgelegt). Gibt die Zahl der Bauteile zurück.
     */
    func addReferenceModel(source: String) throws  -> UInt32
    
    /**
     * Legt eine Unterlage im aktuellen Geschoss an, mittig in der Ansicht.
     * `width` und `height` in Einheiten der Vorlage (PDF-Punkte oder Bildpunkte),
     * `scale` in Metern je Einheit (vor dem Kalibrieren geschätzt).
     */
    func addUnderlay(source: String, page: UInt32, width: Double, height: Double, scale: Double) throws  -> UInt64
    
    /**
     * Befehle für die Befehlspalette: Editor und Ansicht.
     */
    func commands()  -> [CommandItem]
    
    func key(key: KeyInput)  -> EventResult
    
    /**
     * Unterlagen ohne Bild, die die App rendern muss. PNG liest der Kern selbst.
     */
    func missingUnderlayImages()  -> [UnderlayRef]
    
    /**
     * Zwei Finger: in 3D drehen, im Plan verschieben. Bewegung in Punkten.
     */
    func orbit(dx: Float, dy: Float) 
    
    func pan(dx: Float, dy: Float) 
    
    func pointerDown(x: Float, y: Float, clicks: UInt32, shift: Bool)  -> EventResult
    
    func pointerDragged(x: Float, y: Float, shift: Bool)  -> EventResult
    
    func pointerMoved(x: Float, y: Float, shift: Bool)  -> EventResult
    
    func pointerUp()  -> EventResult
    
    /**
     * Das Modell hat sich außerhalb der Ansicht geändert (Eigenschaften, Menü).
     * Rechnet neu und gibt die Zeit in Millisekunden zurück.
     */
    func refresh()  -> Double
    
    /**
     * Zeichnet ein Bild. `false`, wenn das Fenster gerade verdeckt ist; dann erneut versuchen.
     */
    func render() throws  -> Bool
    
    func resize(widthPx: UInt32, heightPx: UInt32, scale: Float) 
    
    /**
     * Führt einen Befehl aus der Befehlspalette aus.
     */
    func runCommand(id: String)  -> EventResult
    
    /**
     * Zeigt ein Dokument. Rechnet alles neu und stellt beide Ansichten auf das ganze Modell ein.
     */
    func setDocument(document: LotDocument)  -> Double
    
    /**
     * Maßstab der Planansicht (100 für 1:100). Der Zoom bleibt gleich groß auf dem Bildschirm.
     */
    func setPlanScale(scale: Double) 
    
    /**
     * Bild einer Unterlage, von der App gerendert (PDF-Seite mit PDFKit oder ein Bild).
     * RGBA mit 8 Bit je Kanal, Zeilen von oben.
     */
    func setUnderlayImage(source: String, page: UInt32, width: UInt32, height: UInt32, rgba: Data) 
    
    func setView(view: ViewKind) 
    
    func state()  -> ViewState
    
    func triangleCount()  -> UInt32
    
    /**
     * Zoomen zum Zeiger. Faktor größer 1 zoomt hinein. `x`, `y`: Lage des
     * Zeigers in Punkten von der Mitte der Ansicht, y nach oben.
     */
    func zoom(factor: Float, x: Float, y: Float) 
    
    func zoomToFit() 
    
}
open class Viewport: ViewportProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

